    return tuple(sorted((r-mr,cc-mc) for r,cc in cs))
def bordercomp(o,g):
    h,w=len(g),len(g[0])
    return any(r==0 or r==h-1 or cc==0 or cc==w-1 for r,cc in o['cells'])
for k in sorted(G):
    if 'input' in k:
        n=k.replace('input','output')
        gi=G[k]; go=G[n]
        ci=comps(gi); co=comps(go)
        chg=set([(r,c) for r in range(len(gi)) for c in range(len(gi[0])) if gi[r][c]!=go[r][c]])
        src=[x for x in ci if any(p in chg for p in x['cells'])][0]
        tgt_color=[o['color'] for o in co if any(p in chg for p in o['cells'])][0]
        shgroups={}
        for o in ci: shgroups.setdefault(nshp(o),[]).append(o)
        grp=shgroups[nshp(src)]
        diff=[t for t in grp if t!=src]
        print(k,'src',src['color'],'size',len(src['cells']),'->tgt',tgt_color,
              'same-shape group colors:',[t['color'] for t in grp],
              'src touches border?',bordercomp(src,gi),'twins:',[(t['color'],bordercomp(t,gi),mind(src,t)) for t in diff])

G=load()
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=-1 and not seen[i][j]:
                col=g[i][j]; q=[(i,j)]; cells=[]
                while q:
                    r,c=q.pop()
                    if seen[r][c]: continue
                    seen[r][c]=True; cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=r+dr,c+dc
                            if 0<=rr<h and 0<=cc<w and g[rr][cc]==col and not seen[rr][cc]: q.append((rr,cc))
                out.append(dict(color=col,cells=sorted(cells)))
    return out
def nshp(c):
    cs=c['cells']; mr=min(r for r,_ in cs); mc=min(cc for _,cc in cs)
    return tuple(sorted((r-mr,cc-mc) for r,cc in cs))
def mind(a,b):
    return min(abs(r1-r2)+abs(c1-c2) for r1,c1 in a['cells'] for r2,c2 in b['cells'])
for k in sorted(G):
    if 'input' in k:
        n=k.replace('input','output')
        gi=G[k]; go=G[n]
        ci=comps(gi); co=comps(go)
        chg=set([(r,c) for r in range(len(gi)) for c in range(len(gi[0])) if gi[r][c]!=go[r][c]])
        src=[x for x in ci if any(p in chg for p in x['cells'])][0]
        tgt_color=[o['color'] for o in co if any(p in chg for p in o['cells'])][0]
        shgroups={}
        for o in ci: shgroups.setdefault(nshp(o),[]).append(o)
        grp=shgroups[nshp(src)]
        diff=[t for t in grp if t!=src]
        # check: target color == twin's color? or something else (e.g. bg-color)?
        twins_col=[d['color'] for d in diff]
        print(k,'src',src['color'],'size',len(src['cells']),'->tgt',tgt_color,'twins:',[(d['color'],bordercomp(d,gi),mind(src,d)) for d in diff],
              'target==twin-col?',tgt_color in twins_col)

